import { describe, expect, it } from "vitest";
import type { GraphEdge, GraphNode } from "../../../api/cascade";
import {
  buildFactionCards,
  externalElements,
  factionStats,
  internalElements,
  type FactionMeta,
} from "./buildElements";
import { computeReveal } from "./reveal";
import { rankNodesByReach } from "./nodeRadius";

function mkNode(overrides: Partial<GraphNode> & { character_id: string }): GraphNode {
  return {
    faction_id: "f1",
    display_name: overrides.character_id,
    follower_count: 0,
    verified: false,
    influence_score: 0,
    degree_in: 0,
    degree_out: 0,
    reach_score: 0,
    engagement_leverage: 0,
    ...overrides,
  };
}

function mkEdge(source: string, target: string, weight = 0.5): GraphEdge {
  return {
    source_character_id: source,
    target_character_id: target,
    edge_type: "follow",
    weight,
  };
}

const METAS: readonly FactionMeta[] = [
  { id: "f1", name: "Independent Media", color: "#3B82F6" },
  { id: "f2", name: "Youth Movement", color: "#10B981" },
];

describe("buildFactionCards", () => {
  it("emits one card per faction meta with member count and top influencer", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1", influence_score: 0.9, display_name: "Anchor" }),
        mkNode({ character_id: "b", faction_id: "f1", influence_score: 0.1, display_name: "Byline" }),
        mkNode({ character_id: "c", faction_id: "f2", influence_score: 0.4, display_name: "Cadet" }),
      ],
      edges: [mkEdge("a", "b"), mkEdge("a", "c")],
    };
    const cards = buildFactionCards(graph, METAS);
    const f1 = cards.find((c) => c.factionId === "f1");
    expect(f1?.name).toBe("Independent Media");
    expect(f1?.memberCount).toBe(2);
    expect(f1?.topInfluencerName).toBe("Anchor");
    // avg influence across f1 members = (0.9 + 0.1) / 2
    expect(f1?.avgInfluence).toBeCloseTo(0.5, 5);
    // only the a→b edge is internal to f1 (a→c crosses to f2)
    expect(f1?.internalTieCount).toBe(1);
  });

  it("renders an empty faction as a zero-stat card with no top influencer", () => {
    const graph = { nodes: [], edges: [] };
    const cards = buildFactionCards(graph, METAS);
    expect(cards).toHaveLength(2);
    expect(cards[0]?.memberCount).toBe(0);
    expect(cards[0]?.avgInfluence).toBe(0);
    expect(cards[0]?.topInfluencerName).toBe("");
    expect(cards[0]?.thumbnailElements).toEqual([]);
  });

  it("includes internal nodes and internal edges in the thumbnail element set", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1" }),
        mkNode({ character_id: "b", faction_id: "f1" }),
        mkNode({ character_id: "c", faction_id: "f2" }),
      ],
      edges: [mkEdge("a", "b"), mkEdge("a", "c")],
    };
    const cards = buildFactionCards(graph, METAS);
    const els = cards.find((c) => c.factionId === "f1")?.thumbnailElements ?? [];
    const nodeIds = els.filter((e) => !e.data.source).map((e) => e.data.id);
    const edgeCount = els.filter((e) => e.data.source).length;
    expect(nodeIds.sort()).toEqual(["a", "b"]);
    expect(edgeCount).toBe(1);
  });
});

describe("factionStats", () => {
  it("summarizes member count, mean influence, top influencer and internal ties", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1", influence_score: 0.9, display_name: "Anchor" }),
        mkNode({ character_id: "b", faction_id: "f1", influence_score: 0.1 }),
        mkNode({ character_id: "c", faction_id: "f2", influence_score: 0.4 }),
      ],
      edges: [mkEdge("a", "b"), mkEdge("a", "c")],
    };
    const stats = factionStats(graph, METAS[0]!);
    expect(stats).toEqual({
      memberCount: 2,
      avgInfluence: 0.5,
      topInfluencerName: "Anchor",
      internalTieCount: 1,
    });
  });
});

describe("externalElements", () => {
  it("emits revealed external nodes (flagged external) plus the cross edges", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1" }),
        mkNode({ character_id: "c", faction_id: "f2", display_name: "Cadet" }),
      ],
      edges: [mkEdge("a", "c")],
    };
    const ranked = rankNodesByReach(graph.nodes);
    const reveal = computeReveal(graph, "f1", { crossFilterFactionId: "f2", pinnedNodeId: null });
    const els = externalElements(graph, METAS, reveal, ranked);
    const nodeEl = els.find((e) => e.data.id === "c");
    expect(nodeEl?.data.external).toBe(true);
    expect(nodeEl?.data.color).toBe("#10B981"); // colored by its OWN faction (f2)
    expect(els.some((e) => e.data.source === "a" && e.data.target === "c")).toBe(true);
  });

  it("is empty when nothing is revealed", () => {
    const graph = {
      nodes: [mkNode({ character_id: "a", faction_id: "f1" }), mkNode({ character_id: "c", faction_id: "f2" })],
      edges: [mkEdge("a", "c")],
    };
    const ranked = rankNodesByReach(graph.nodes);
    const reveal = computeReveal(graph, "f1", { crossFilterFactionId: null, pinnedNodeId: null });
    expect(externalElements(graph, METAS, reveal, ranked)).toEqual([]);
  });
});

describe("edge dedupe — one line per pair, arrows encode direction", () => {
  it("collapses a reciprocal internal pair into one MUTUAL edge with the max weight and a sorted id", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "b", faction_id: "f1" }),
        mkNode({ character_id: "a", faction_id: "f1" }),
      ],
      // A→B and B→A: reciprocal, so one line with arrows on both ends.
      edges: [mkEdge("b", "a", 0.4), mkEdge("a", "b", 0.9)],
    };
    const ranked = rankNodesByReach(graph.nodes);
    const edges = internalElements(graph, METAS[0]!, ranked).filter((e) => e.data.source);
    expect(edges).toHaveLength(1);
    expect(edges[0]?.data.direction).toBe("mutual");
    expect(edges[0]?.data.weight).toBe(0.9);
    expect(edges[0]?.data.id).toBe("a~b"); // canonical (sorted) pair id
  });

  it("keeps a one-way internal follow as a FORWARD edge pointing at the followee", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "b", faction_id: "f1" }),
        mkNode({ character_id: "a", faction_id: "f1" }),
      ],
      // Only B→A: B follows A, so the single arrow points at A.
      edges: [mkEdge("b", "a", 0.5)],
    };
    const ranked = rankNodesByReach(graph.nodes);
    const edges = internalElements(graph, METAS[0]!, ranked).filter((e) => e.data.source);
    expect(edges).toHaveLength(1);
    expect(edges[0]?.data.direction).toBe("forward");
    expect(edges[0]?.data.source).toBe("b"); // follower
    expect(edges[0]?.data.target).toBe("a"); // followee (arrow end)
    expect(edges[0]?.data.id).toBe("a~b"); // still the canonical sorted id
  });

  it("keeps two distinct internal pairs as two edges", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1" }),
        mkNode({ character_id: "b", faction_id: "f1" }),
        mkNode({ character_id: "c", faction_id: "f1" }),
      ],
      edges: [mkEdge("a", "b"), mkEdge("b", "c")],
    };
    const ranked = rankNodesByReach(graph.nodes);
    const edges = internalElements(graph, METAS[0]!, ranked).filter((e) => e.data.source);
    expect(edges).toHaveLength(2);
  });

  it("collapses reciprocal cross-faction edges into one mutual edge in externalElements too", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1" }),
        mkNode({ character_id: "c", faction_id: "f2" }),
      ],
      edges: [mkEdge("a", "c", 0.3), mkEdge("c", "a", 0.7)],
    };
    const ranked = rankNodesByReach(graph.nodes);
    const reveal = computeReveal(graph, "f1", { crossFilterFactionId: "f2", pinnedNodeId: null });
    const edges = externalElements(graph, METAS, reveal, ranked).filter((e) => e.data.source);
    expect(edges).toHaveLength(1);
    expect(edges[0]?.data.direction).toBe("mutual");
    expect(edges[0]?.data.weight).toBe(0.7);
    expect(edges[0]?.data.id).toBe("a~c");
  });
});

describe("internalElements", () => {
  it("builds faction-scoped node elements carrying color and reach radius", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1", reach_score: 0.9 }),
        mkNode({ character_id: "c", faction_id: "f2", reach_score: 0.9 }),
      ],
      edges: [mkEdge("a", "c")],
    };
    const ranked = rankNodesByReach(graph.nodes);
    const els = internalElements(graph, METAS[0]!, ranked);
    const nodeEl = els.find((e) => e.data.id === "a");
    expect(nodeEl?.data.color).toBe("#3B82F6");
    expect(typeof nodeEl?.data.radius).toBe("number");
    // the a→c edge is cross-faction, so it is NOT an internal element
    expect(els.some((e) => e.data.source)).toBe(false);
  });
});


