/**
 * focusLayout — DETERMINISTIC radial placement for the focus canvas.
 *
 * The focus graph is small and often chain-like (a hub with a few members and a
 * handful of revealed cross-faction ties). A force layout (cose-bilkent) can
 * degenerate on such graphs and collapse them into a straight diagonal line.
 * Instead we compute fixed positions and feed cytoscape's `preset` layout:
 *   - the highest-influence member is the hub at the center;
 *   - the remaining members sit evenly on an INTERNAL ring around it;
 *   - revealed external nodes sit on an OUTER ring, grouped into contiguous arcs
 *     by faction, always beyond the internal ring.
 *
 * Pure and deterministic (no jitter) so it is unit-testable and never re-jitters
 * on reveal. Coordinates are model-space; the canvas fits the viewport to them.
 */

export interface FocusLayoutNode {
  readonly id: string;
  /** Ordering weight — highest becomes the hub; also orders ring placement. */
  readonly weight: number;
  readonly factionId: string;
}

export interface Point {
  readonly x: number;
  readonly y: number;
}

export const FOCUS_INTERNAL_RADIUS = 160;
export const FOCUS_OUTER_RADIUS = 340;

/** Stable descending-weight sort, tie-broken by id for determinism. */
function byWeight(a: FocusLayoutNode, b: FocusLayoutNode): number {
  return b.weight - a.weight || a.id.localeCompare(b.id);
}

export function computeFocusPositions(
  members: readonly FocusLayoutNode[],
  externals: readonly FocusLayoutNode[],
): Map<string, Point> {
  const pos = new Map<string, Point>();

  // ── Internal: hub at center, the rest on a ring. ──
  const sortedMembers = [...members].sort(byWeight);
  const satellites = sortedMembers.length - 1;
  sortedMembers.forEach((node, i) => {
    if (i === 0) {
      pos.set(node.id, { x: 0, y: 0 });
      return;
    }
    const angle = ((i - 1) / satellites) * 2 * Math.PI - Math.PI / 2;
    pos.set(node.id, {
      x: Math.cos(angle) * FOCUS_INTERNAL_RADIUS,
      y: Math.sin(angle) * FOCUS_INTERNAL_RADIUS,
    });
  });

  // ── External: grouped by faction (sorted), contiguous arcs on the outer ring. ──
  const byFaction = new Map<string, FocusLayoutNode[]>();
  for (const ext of externals) {
    const bucket = byFaction.get(ext.factionId);
    if (bucket) bucket.push(ext);
    else byFaction.set(ext.factionId, [ext]);
  }
  const factionIds = [...byFaction.keys()].sort();
  const total = externals.length;
  let placed = 0;
  for (const fid of factionIds) {
    const group = [...byFaction.get(fid)!].sort(byWeight);
    for (const node of group) {
      const angle = total <= 1 ? -Math.PI / 2 : (placed / total) * 2 * Math.PI - Math.PI / 2;
      pos.set(node.id, {
        x: Math.cos(angle) * FOCUS_OUTER_RADIUS,
        y: Math.sin(angle) * FOCUS_OUTER_RADIUS,
      });
      placed += 1;
    }
  }

  return pos;
}


