function mkNode(overrides: Partial<GraphNode> & { character_id: string }): GraphNode {
  return {
    faction_id: "f1",
    display_name: overrides.character_id,
    follower_count: 0,
    verified: false,
    influence_score: 0,
    degree_in: 0,
    degree_out: 0,
    reach_score: 0,
    engagement_leverage: 0,
    ...overrides,
  };
}

function mkEdge(source: string, target: string): GraphEdge {
  return { source_character_id: source, target_character_id: target, edge_type: "follow", weight: 0.5 };
}

const METAS: readonly FactionMeta[] = [
  { id: "f1", name: "Independent Media", color: "#3B82F6" },
  { id: "f2", name: "Youth Movement", color: "#10B981" },
];

const GRAPH = {
  nodes: [
    mkNode({ character_id: "a", faction_id: "f1", display_name: "Anchor", reach_score: 0.9, follower_count: 900, degree_out: 3, verified: true, influence_score: 0.8 }),
    mkNode({ character_id: "b", faction_id: "f1", display_name: "Byline", reach_score: 0.5, follower_count: 100 }),
    mkNode({ character_id: "c", faction_id: "f2", display_name: "Cadet", reach_score: 0.7, follower_count: 300 }),
  ],
  edges: [mkEdge("a", "b"), mkEdge("a", "c")],
};

describe("buildNodeInspection", () => {
  it("reports rank, followers/following, faction name/color and verification", () => {
    const ranked = rankNodesByReach(GRAPH.nodes);
    const insp = buildNodeInspection(GRAPH, ranked, "a", METAS);
    expect(insp).not.toBeNull();
    expect(insp?.displayName).toBe("Anchor");
    expect(insp?.factionName).toBe("Independent Media");
    expect(insp?.factionColor).toBe("#3B82F6");
    expect(insp?.verified).toBe(true);
    expect(insp?.followerCount).toBe(900);
    expect(insp?.followingCount).toBe(3);
    // a has the highest reach → rank 1 of 3
    expect(insp?.rank).toBe(1);
    expect(insp?.total).toBe(3);
  });

  it("lists top connections including cross-faction ones, flagged external", () => {
    const ranked = rankNodesByReach(GRAPH.nodes);
    const insp = buildNodeInspection(GRAPH, ranked, "a", METAS);
    const conns = insp?.topConnections ?? [];
    // a connects to c (f2, reach .7) and b (f1, reach .5) → c first by reach
    expect(conns.map((c) => c.characterId)).toEqual(["c", "b"]);
    const cadet = conns.find((c) => c.characterId === "c");
    expect(cadet?.external).toBe(true);
    expect(cadet?.factionName).toBe("Youth Movement");
    const byline = conns.find((c) => c.characterId === "b");
    expect(byline?.external).toBe(false);
  });

  it("returns null for an unknown character id", () => {
    const ranked = rankNodesByReach(GRAPH.nodes);
    expect(buildNodeInspection(GRAPH, ranked, "missing", METAS)).toBeNull();
  });

  it("degrades to a null faction name when the meta is absent", () => {
    const ranked = rankNodesByReach(GRAPH.nodes);
    const insp = buildNodeInspection(GRAPH, ranked, "c", []);
    expect(insp?.factionName).toBeNull();
    expect(insp?.factionColor).toBeNull();
  });
});


