/**
 * inspector — pure computation of the pinned-node inspector payload (AC4):
 * overall reach rank, followers / following, faction name+color, and the top
 * connections (cross-faction ones included, flagged external). Kept pure so
 * the focus canvas inspector is a dumb renderer over this output.
 */

import type { GraphNode } from "../../../api/cascade";
import type { FactionMeta, FollowGraphLike } from "./buildElements";
import { compareByReachDesc, type RankedNode } from "./nodeRadius";

export interface Connection {
  readonly characterId: string;
  readonly displayName: string;
  /** Localized faction name, or null when the connection's faction has no meta. */
  readonly factionName: string | null;
  readonly external: boolean;
}

export interface NodeInspection {
  readonly characterId: string;
  readonly displayName: string;
  readonly factionName: string | null;
  readonly factionColor: string | null;
  readonly verified: boolean;
  /** 1-based reach rank across the whole roster. */
  readonly rank: number;
  readonly total: number;
  readonly followerCount: number;
  readonly followingCount: number;
  readonly reachScore: number;
  readonly influenceScore: number;
  readonly topConnections: readonly Connection[];
}

const DEFAULT_CONNECTION_LIMIT = 6;

/**
 * buildNodeInspection — assemble the inspector payload for one character, or
 * null when the id is not in the graph. Top connections are the node's direct
 * neighbors sorted by reach (descending), capped at `limit`.
 */
export function buildNodeInspection(
  graph: FollowGraphLike,
  ranked: readonly RankedNode[],
  characterId: string,
  metas: readonly FactionMeta[],
  limit: number = DEFAULT_CONNECTION_LIMIT,
): NodeInspection | null {
  const nodeById = new Map(graph.nodes.map((n) => [n.character_id, n]));
  const node = nodeById.get(characterId);
  if (!node) return null;

  const metaById = new Map(metas.map((meta) => [meta.id, meta]));
  const reachRankById = new Map(ranked.map((r) => [r.node.character_id, r.rank]));
  const ownMeta = metaById.get(node.faction_id);

  const neighborIds = new Set<string>();
  for (const edge of graph.edges) {
    if (edge.source_character_id === characterId) neighborIds.add(edge.target_character_id);
    if (edge.target_character_id === characterId) neighborIds.add(edge.source_character_id);
  }

  const topConnections: Connection[] = [...neighborIds]
    .map((id) => nodeById.get(id))
    .filter((n): n is GraphNode => n !== undefined)
    .sort(compareByReachDesc)
    .slice(0, limit)
    .map((n) => ({
      characterId: n.character_id,
      displayName: n.display_name,
      factionName: metaById.get(n.faction_id)?.name ?? null,
      external: n.faction_id !== node.faction_id,
    }));

  return {
    characterId: node.character_id,
    displayName: node.display_name,
    factionName: ownMeta?.name ?? null,
    factionColor: ownMeta?.color ?? null,
    verified: node.verified,
    rank: (reachRankById.get(characterId) ?? 0) + 1,
    total: ranked.length,
    followerCount: node.follower_count,
    followingCount: node.degree_out,
    reachScore: node.reach_score,
    influenceScore: node.influence_score,
    topConnections,
  };
}


