/**
 * nodeRadius — reach-driven node sizing for the Direction-3 faction network.
 *
 * Mirrors files-mfe's `kn.node.r-*` degree bands, but keyed on the Range
 * follow-graph's live `reach_score` signal (the Living-Graph convention: reach
 * drives node radius — see api/cascade.ts GraphNode.reach_score). The scale is
 * exposed as `rn.node.r-*` constants so the focus canvas and the bento
 * thumbnails size nodes identically without importing files-mfe tokens.
 *
 * Cytoscape needs numeric px radii at element-construction time (it does not
 * resolve CSS vars in its style mapper), so these are literal constants.
 */

import type { GraphNode } from "../../../api/cascade";

/** rn.node.r-* — px radii by reach percentile band (hub → small). */
export const RN_NODE_RADIUS = {
  hub: 32,
  large: 26,
  medium: 22,
  small: 14,
} as const;

export interface RankedNode {
  readonly node: GraphNode;
  /** 0-based reach rank; 0 = highest reach in the ranked set. */
  readonly rank: number;
  readonly radius: number;
}

/**
 * radiusForRank — map a 0-based reach rank to a px radius by percentile band:
 * top 10% → hub, next → large (≤25%), next → medium (≤35%), tail → small.
 * A single node (or an empty set) never divides by zero.
 */
export function radiusForRank(rank: number, total: number): number {
  if (total <= 0) return RN_NODE_RADIUS.small;
  const pct = total <= 1 ? 0 : rank / (total - 1);
  if (pct <= 0.1) return RN_NODE_RADIUS.hub;
  if (pct <= 0.25) return RN_NODE_RADIUS.large;
  if (pct <= 0.35) return RN_NODE_RADIUS.medium;
  return RN_NODE_RADIUS.small;
}

/**
 * compareByReachDesc — reach-descending comparator, tie-broken by
 * `follower_count` then `character_id` for a stable, deterministic order.
 * Shared with the inspector's top-connections sort so the two can't diverge.
 */
export function compareByReachDesc(a: GraphNode, b: GraphNode): number {
  return (
    b.reach_score - a.reach_score ||
    b.follower_count - a.follower_count ||
    a.character_id.localeCompare(b.character_id)
  );
}

/**
 * rankNodesByReach — sort nodes descending by `reach_score`, tie-broken by
 * `follower_count` then `character_id` for a stable, deterministic order, and
 * attach each node's rank + reach-banded radius.
 */
export function rankNodesByReach(nodes: readonly GraphNode[]): readonly RankedNode[] {
  const sorted = [...nodes].sort(compareByReachDesc);
  const total = sorted.length;
  return sorted.map((node, rank) => ({
    node,
    rank,
    radius: radiusForRank(rank, total),
  }));
