/**
 * reveal — the Direction-3 progressive-disclosure core (AC3).
 *
 * The focus canvas opens CLEAN: only a faction's internal ties are drawn.
 * Cross-faction ties are revealed ONLY on an explicit selection — a per-faction
 * tie chip (reveal that one faction's ties) or a pinned node (reveal that one
 * node's own cross ties). There is deliberately NO "show all cross-faction
 * ties" affordance — the operator rejected it. `computeReveal` is the single
 * pure function both selections feed into; the canvas just renders its output.
 */

import type { GraphEdge, GraphNode } from "../../../api/cascade";
import type { FactionMeta, FollowGraphLike } from "./buildElements";

export interface RevealState {
  /** A selected cross-faction tie chip, or null. */
  readonly crossFilterFactionId: string | null;
  /** A pinned node (internal or already-revealed external), or null. */
  readonly pinnedNodeId: string | null;
}

export interface RevealResult {
  /** External (non-focus-faction) node ids to draw. */
  readonly externalNodeIds: ReadonlySet<string>;
  /** The cross-faction edges to draw. */
  readonly crossEdges: readonly GraphEdge[];
}

/** One row of the cross-faction tie strip: an external faction + its tie count. */
export interface CrossFactionTie {
  readonly factionId: string;
  readonly name: string;
  readonly color: string;
  readonly tieCount: number;
}

function factionByCharacter(nodes: readonly GraphNode[]): Map<string, string> {
  return new Map(nodes.map((n) => [n.character_id, n.faction_id]));
}

/**
 * computeReveal — given the focus faction and the current selection, return the
 * external nodes + cross edges to draw. Clean state (both selections null) →
 * nothing. A chip reveals every tie to that one external faction; a pinned node
 * reveals every cross tie incident to that node; both together union. No edge
 * is ever revealed without an explicit selection.
 */
export function computeReveal(
  graph: FollowGraphLike,
  focusFactionId: string,
  state: RevealState,
): RevealResult {
  const facOf = factionByCharacter(graph.nodes);
  const externalNodeIds = new Set<string>();
  const crossEdges: GraphEdge[] = [];
  const { crossFilterFactionId, pinnedNodeId } = state;

  if (crossFilterFactionId === null && pinnedNodeId === null) {
    return { externalNodeIds, crossEdges };
  }

  for (const edge of graph.edges) {
    const sFac = facOf.get(edge.source_character_id);
    const tFac = facOf.get(edge.target_character_id);
    const sInside = sFac === focusFactionId;
    const tInside = tFac === focusFactionId;
    if (sInside === tInside) continue; // not a cross-faction edge for this focus

    const insideId = sInside ? edge.source_character_id : edge.target_character_id;
    const outsideId = sInside ? edge.target_character_id : edge.source_character_id;
    const outsideFac = sInside ? tFac : sFac;

    const byChip =
      crossFilterFactionId !== null && outsideFac === crossFilterFactionId;
    const byPin =
      pinnedNodeId !== null &&
      (insideId === pinnedNodeId || outsideId === pinnedNodeId);

    if (byChip || byPin) {
      externalNodeIds.add(outsideId);
      crossEdges.push(edge);
    }
  }

  return { externalNodeIds, crossEdges };
}

/**
 * crossFactionSummary — the per-external-faction tie counts backing the tie
 * chips, descending by count. Factions without a supplied FactionMeta are
 * skipped (their opaque id is never displayable).
 */
export function crossFactionSummary(
  graph: FollowGraphLike,
  focusFactionId: string,
  metas: readonly FactionMeta[],
): readonly CrossFactionTie[] {
  const facOf = factionByCharacter(graph.nodes);
  const metaById = new Map(metas.map((meta) => [meta.id, meta]));
  const counts = new Map<string, number>();

  for (const edge of graph.edges) {
    const sFac = facOf.get(edge.source_character_id);
    const tFac = facOf.get(edge.target_character_id);
    const sInside = sFac === focusFactionId;
    const tInside = tFac === focusFactionId;
    if (sInside === tInside) continue;
    const outsideFac = sInside ? tFac : sFac;
    if (outsideFac === undefined) continue;
    counts.set(outsideFac, (counts.get(outsideFac) ?? 0) + 1);
  }

  const rows: CrossFactionTie[] = [];
  for (const [factionId, tieCount] of counts) {
    const meta = metaById.get(factionId);
    if (!meta) continue;
    rows.push({ factionId, name: meta.name, color: meta.color, tieCount });
  }
  rows.sort((a, b) => b.tieCount - a.tieCount || a.name.localeCompare(b.name));
  return rows;
}


