    const byId = new Map(layout.nodes.map((n) => [n.id, n]));
    // b has the largest radius → hub at the center of a 100×100 box.
    expect(byId.get("b")).toMatchObject({ x: 50, y: 50 });
    // the satellites sit on a ring away from the center.
    const a = byId.get("a")!;
    const dist = Math.hypot(a.x - 50, a.y - 50);
    expect(dist).toBeGreaterThan(20);
    expect(layout.nodes).toHaveLength(3);
  });

  it("maps internal edges to endpoint segments and drops dangling ones", () => {
    const els = [node("a", 10), node("b", 30), edge("a", "b"), edge("a", "z")];
    const layout = layoutThumbnail(els, 100);
    expect(layout.segments).toHaveLength(1);
    expect(layout.segments[0]).toHaveProperty("x1");
  });

