/**
 * thumbnailLayout — a tiny deterministic radial layout for the bento card
 * mini-graphs. The thumbnails are decorative previews (a dozen dots at most),
 * so a cheap hub-and-ring placement rendered as inline SVG is clearer, faster,
 * and far more testable than spinning up a cytoscape instance per card. The
 * highest-reach member sits at the center; the rest fan out on a ring.
 */

import type { CyElement } from "./buildElements";

export interface PositionedNode {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly r: number;
  readonly color: string;
}

export interface Segment {
  readonly x1: number;
  readonly y1: number;
  readonly x2: number;
  readonly y2: number;
}

export interface ThumbnailLayout {
  readonly nodes: readonly PositionedNode[];
  readonly segments: readonly Segment[];
}

const HUB_R = 5.5;
const SATELLITE_R = 3.5;

/** Split a mixed element list into node elements and edge elements. */
function partition(elements: readonly CyElement[]): {
  nodes: readonly CyElement[];
  edges: readonly CyElement[];
} {
  const nodes = elements.filter((e) => e.data.source === undefined);
  const edges = elements.filter((e) => e.data.source !== undefined);
  return { nodes, edges };
}

export function layoutThumbnail(
  elements: readonly CyElement[],
  size: number,
): ThumbnailLayout {
  const { nodes, edges } = partition(elements);
  if (nodes.length === 0) return { nodes: [], segments: [] };

  // Hub = highest radius (reach), tie-broken by id for determinism.
  const ordered = [...nodes].sort(
    (a, b) => (b.data.radius ?? 0) - (a.data.radius ?? 0) || a.data.id.localeCompare(b.data.id),
  );
  const cx = size / 2;
  const cy = size / 2;
  const ringRadius = size * 0.34;

  const positioned: PositionedNode[] = ordered.map((el, i) => {
    if (i === 0) {
      // design-ratchet-allow: canvas-render
      // Thumbnail node fill passed to the canvas layout renderer.
      return { id: el.data.id, x: cx, y: cy, r: HUB_R, color: el.data.color ?? "#888" };
    }
    const satellites = ordered.length - 1;
    const angle = ((i - 1) / satellites) * Math.PI * 2 - Math.PI / 2;
    return {
      id: el.data.id,
      x: cx + Math.cos(angle) * ringRadius,
      y: cy + Math.sin(angle) * ringRadius,
      r: SATELLITE_R,
      color: el.data.color ?? "#888",
    };
  });

  const posById = new Map(positioned.map((p) => [p.id, p]));
  const segments: Segment[] = [];
  for (const e of edges) {
    const a = posById.get(e.data.source ?? "");
    const b = posById.get(e.data.target ?? "");
    if (!a || !b) continue;
    segments.push({ x1: a.x, y1: a.y, x2: b.x, y2: b.y });
  }

  return { nodes: positioned, segments };
}



