    source_character_id: source,
    target_character_id: target,
    edge_type: "follow",
    weight,
  };
}

const METAS: readonly FactionMeta[] = [
  { id: "f1", name: "Independent Media", color: "#3B82F6" },
  { id: "f2", name: "Youth Movement", color: "#10B981" },
];

