  it("emits one card per faction meta with member count and top influencer", () => {
    const graph = {
      nodes: [
        mkNode({ character_id: "a", faction_id: "f1", influence_score: 0.9, display_name: "Anchor" }),
        mkNode({ character_id: "b", faction_id: "f1", influence_score: 0.1, display_name: "Byline" }),
        mkNode({ character_id: "c", faction_id: "f2", influence_score: 0.4, display_name: "Cadet" }),
