    expect(f1?.internalTieCount).toBe(1);
  });

  it("renders an empty faction as a zero-stat card with no top influencer", () => {
    const graph = { nodes: [], edges: [] };
    const cards = buildFactionCards(graph, METAS);
    expect(cards).toHaveLength(2);
    expect(cards[0]?.memberCount).toBe(0);
    expect(cards[0]?.avgInfluence).toBe(0);
    expect(cards[0]?.topInfluencerName).toBe("");
