      edges: [mkEdge("a", "b"), mkEdge("a", "c")],
    };
    const cards = buildFactionCards(graph, METAS);
    const els = cards.find((c) => c.factionId === "f1")?.thumbnailElements ?? [];
    const nodeIds = els.filter((e) => !e.data.source).map((e) => e.data.id);
