/**
 * buildElements — pure transforms from the follow-graph data contract
 * (api/cascade.ts FollowGraph) + a client-side faction-name map into the
 * cytoscape element sets and bento-card stats the Direction-3 network view
 * renders. All the real logic lives here so it can be unit-tested directly;
 * the cytoscape components (which render to <canvas> and can't run under
 * jsdom) are thin shells over these outputs.
 *
 * `faction_id` is opaque and never displayed — callers join names client-side
 * (GraphNode.faction_display_name is normally absent) and pass a FactionMeta
 * list. Node radius is reach-driven (see nodeRadius.rankNodesByReach); card
 * "influence" stats use the centrality `influence_score` signal.
 */

import type { EdgeType, GraphEdge, GraphNode } from "../../../api/cascade";
import { rankNodesByReach, type RankedNode } from "./nodeRadius";

export interface FollowGraphLike {
  readonly nodes: readonly GraphNode[];
  readonly edges: readonly GraphEdge[];
}

/** Client-side faction name + color join. `id` is the opaque faction_id. */
export interface FactionMeta {
  readonly id: string;
  readonly name: string;
  readonly color: string;
}

/**
 * Edge direction, driving the arrowheads:
 * - "forward": a one-way follow — source follows target, one arrow at target.
 * - "mutual": a reciprocal follow — one line, arrows on BOTH ends.
 */
export type EdgeDirection = "forward" | "mutual";

/** A cytoscape ElementDefinition-compatible node or edge. */
export interface CyElement {
  readonly data: {
    readonly id: string;
    readonly label?: string;
    readonly source?: string;
    readonly target?: string;
    readonly color?: string;
    readonly radius?: number;
    readonly external?: boolean;
    readonly edgeType?: EdgeType;
    readonly weight?: number;
    readonly direction?: EdgeDirection;
  };
}

export interface FactionCard {
  readonly factionId: string;
  readonly name: string;
  readonly color: string;
  readonly memberCount: number;
  /** Mean centrality (`influence_score`) across faction members; 0 when empty. */
  readonly avgInfluence: number;
  /** Display name of the highest-influence member; "" when the faction is empty. */
  readonly topInfluencerName: string;
  readonly internalTieCount: number;
  /** Internal-only node + edge elements for the card's mini-graph thumbnail. */
  readonly thumbnailElements: readonly CyElement[];
}

/** Index a ranked list by character id for O(1) radius lookups. */
function radiusByCharacter(ranked: readonly RankedNode[]): Map<string, number> {
  return new Map(ranked.map((r) => [r.node.character_id, r.radius]));
}

/** Build the cytoscape node element for a single graph node. */
function nodeElement(
  node: GraphNode,
  color: string,
  radius: number,
  external: boolean,
): CyElement {
  return {
    data: {
      id: node.character_id,
      label: node.display_name,
      color,
      radius,
      external,
    },
  };
}

interface PairAgg {
  readonly lo: string;
  readonly hi: string;
  edgeType: EdgeType;
  weight: number;
  loToHi: boolean; // saw a follow in the lo→hi direction
  hiToLo: boolean; // saw a follow in the hi→lo direction
}

/**
 * edgeElements — collapse a directed edge list into ONE cytoscape line per
 * connected pair. Two parallel lines for a reciprocal follow (A→B and B→A) are
 * pure noise, so we dedupe by the UNORDERED {source,target} pair (canonical key
 * = the two ids sorted, which also gives a stable element id). Direction is
 * preserved as arrowheads via `data.direction`: a one-way tie is "forward" with
 * source=follower / target=followee (one arrow at the followee); a reciprocal
 * tie is "mutual" (arrows on both ends). Collapsed weight is the MAX across the
 * merged edges (the strongest tie wins).
 */
function edgeElements(edges: readonly GraphEdge[]): CyElement[] {
  const byPair = new Map<string, PairAgg>();
  for (const edge of edges) {
    const s = edge.source_character_id;
    const t = edge.target_character_id;
    const [lo, hi] = s <= t ? ([s, t] as const) : ([t, s] as const);
    const key = `${lo}~${hi}`;
    const isLoToHi = s === lo;
    const existing = byPair.get(key);
    if (existing) {
      existing.weight = Math.max(existing.weight, edge.weight);
      if (isLoToHi) existing.loToHi = true;
      else existing.hiToLo = true;
    } else {
      byPair.set(key, {
        lo,
        hi,
        edgeType: edge.edge_type,
        weight: edge.weight,
        loToHi: isLoToHi,
        hiToLo: !isLoToHi,
      });
    }
  }
  return [...byPair.values()].map((p) => {
    const mutual = p.loToHi && p.hiToLo;
    // Forward one-way: orient source=follower → target=followee so the single
    // arrow points at the followee. Mutual: orientation is irrelevant (both ends
    // arrowed), so keep the canonical lo→hi order.
    const forwardLoToHi = mutual || p.loToHi;
    return {
      data: {
        id: `${p.lo}~${p.hi}`,
        source: forwardLoToHi ? p.lo : p.hi,
        target: forwardLoToHi ? p.hi : p.lo,
        edgeType: p.edgeType,
        weight: p.weight,
        direction: mutual ? "mutual" : "forward",
      },
    };
  });
}

/**
 * internalElements — the node + edge elements wholly inside one faction:
 * every member node (colored + reach-sized) plus every edge whose BOTH
 * endpoints are members. Cross-faction edges are excluded (they are revealed
 * progressively by the focus canvas, never at open).
 */
export function internalElements(
  graph: FollowGraphLike,
  meta: FactionMeta,
  ranked: readonly RankedNode[],
): readonly CyElement[] {
  const radii = radiusByCharacter(ranked);
  const members = graph.nodes.filter((n) => n.faction_id === meta.id);
  const memberIds = new Set(members.map((n) => n.character_id));
  const nodeEls = members.map((n) =>
    nodeElement(n, meta.color, radii.get(n.character_id) ?? 0, false),
  );
  const edgeEls = edgeElements(
    graph.edges.filter(
      (e) =>
        memberIds.has(e.source_character_id) &&
        memberIds.has(e.target_character_id),
    ),
  );
  return [...nodeEls, ...edgeEls];
}

/** Pick the highest-`influence_score` member (tie-break followers, then id). */
function topInfluencer(members: readonly GraphNode[]): GraphNode | null {
  if (members.length === 0) return null;
  return [...members].sort(
    (a, b) =>
      b.influence_score - a.influence_score ||
      b.follower_count - a.follower_count ||
      a.character_id.localeCompare(b.character_id),
  )[0]!;
}

export interface FactionStats {
  readonly memberCount: number;
  /** Mean centrality (`influence_score`) across members; 0 when empty. */
  readonly avgInfluence: number;
  readonly topInfluencerName: string;
  readonly internalTieCount: number;
}

/**
 * factionStats — the headline numbers for one faction, shared by the bento
 * card and the focus canvas stats panel so both read identically.
 */
export function factionStats(graph: FollowGraphLike, meta: FactionMeta): FactionStats {
  const members = graph.nodes.filter((n) => n.faction_id === meta.id);
  const memberIds = new Set(members.map((n) => n.character_id));
  const internalTieCount = graph.edges.filter(
    (e) =>
      memberIds.has(e.source_character_id) && memberIds.has(e.target_character_id),
  ).length;
  const avgInfluence =
    members.length === 0
      ? 0
      : members.reduce((sum, n) => sum + n.influence_score, 0) / members.length;
  return {
    memberCount: members.length,
    avgInfluence,
    topInfluencerName: topInfluencer(members)?.display_name ?? "",
    internalTieCount,
  };
}

/**
 * externalElements — the cytoscape elements for a revealed cross-faction slice:
 * each revealed external node (colored by its OWN faction so the operator sees
 * where the tie leads) plus the cross edges. Driven entirely by a RevealResult
 * (reveal.ts) so nothing is ever drawn without an explicit selection.
 */
export function externalElements(
  graph: FollowGraphLike,
  metas: readonly FactionMeta[],
  revealed: {
    readonly externalNodeIds: ReadonlySet<string>;
    readonly crossEdges: readonly GraphEdge[];
  },
  ranked: readonly RankedNode[],
): readonly CyElement[] {
  const radii = radiusByCharacter(ranked);
  const colorByFaction = new Map(metas.map((meta) => [meta.id, meta.color]));
  const nodeById = new Map(graph.nodes.map((n) => [n.character_id, n]));

  const nodeEls: CyElement[] = [];
  for (const id of revealed.externalNodeIds) {
    const node = nodeById.get(id);
    if (!node) continue;
    nodeEls.push(
      // design-ratchet-allow: canvas-render
      // Node fill handed to the cytoscape graph renderer, which takes a colour
      // STRING; no utility class reaches a canvas element.
      nodeElement(node, colorByFaction.get(node.faction_id) ?? "#64748B", radii.get(id) ?? 0, true),
    );
  }
  const edgeEls = edgeElements(revealed.crossEdges);
  return [...nodeEls, ...edgeEls];
}

/**
 * buildFactionCards — one card per FactionMeta with member count, mean
 * influence, top influencer name, internal-tie count, and the mini-graph
 * thumbnail element set. Reach ranking is computed once across the whole
 * roster so thumbnail node sizes match the focus canvas.
 */
export function buildFactionCards(
  graph: FollowGraphLike,
  metas: readonly FactionMeta[],
): readonly FactionCard[] {
  const ranked = rankNodesByReach(graph.nodes);
  return metas.map((meta) => {
    const stats = factionStats(graph, meta);
    return {
      factionId: meta.id,
      name: meta.name,
      color: meta.color,
      memberCount: stats.memberCount,
      avgInfluence: stats.avgInfluence,
      topInfluencerName: stats.topInfluencerName,
      internalTieCount: stats.internalTieCount,
      thumbnailElements: internalElements(graph, meta, ranked),
    };
  });
}


