import {
  computeFocusPositions,
  FOCUS_INTERNAL_RADIUS,
  FOCUS_OUTER_RADIUS,
  type FocusLayoutNode,
} from "./focusLayout";

function member(id: string, weight: number, factionId = "f1"): FocusLayoutNode {
  return { id, weight, factionId };
}

const dist = (p: { x: number; y: number }) => Math.hypot(p.x, p.y);

describe("computeFocusPositions", () => {
  it("places the highest-weight member at the hub (center)", () => {
    const pos = computeFocusPositions(
      [member("a", 0.2), member("b", 0.9), member("c", 0.5)],
      [],
    );
    expect(pos.get("b")).toEqual({ x: 0, y: 0 });
  });

  it("places remaining members on the internal ring", () => {
    const pos = computeFocusPositions(
      [member("a", 0.9), member("b", 0.5), member("c", 0.3), member("d", 0.1)],
      [],
    );
    for (const id of ["b", "c", "d"]) {
      expect(dist(pos.get(id)!)).toBeCloseTo(FOCUS_INTERNAL_RADIUS, 5);
    }
  });

  it("places revealed externals on an OUTER ring, beyond the internal ring", () => {
    const pos = computeFocusPositions(
      [member("a", 0.9), member("b", 0.5)],
      [member("x", 0.4, "f2"), member("y", 0.2, "f3")],
    );
    for (const id of ["x", "y"]) {
      expect(dist(pos.get(id)!)).toBeCloseTo(FOCUS_OUTER_RADIUS, 5);
    }
    expect(FOCUS_OUTER_RADIUS).toBeGreaterThan(FOCUS_INTERNAL_RADIUS);
  });

  it("does NOT collapse to a line — positions spread across 2D", () => {
    const pos = computeFocusPositions(
      [member("a", 0.9), member("b", 0.7), member("c", 0.5), member("d", 0.3)],
      [member("x", 0.4, "f2"), member("y", 0.2, "f2"), member("z", 0.1, "f3")],
    );
    const xs = [...pos.values()].map((p) => p.x);
    const ys = [...pos.values()].map((p) => p.y);
    const xRange = Math.max(...xs) - Math.min(...xs);
    const yRange = Math.max(...ys) - Math.min(...ys);
    expect(xRange).toBeGreaterThan(0);
    expect(yRange).toBeGreaterThan(0);
    // A collinear (degenerate) layout would have some triple with zero area for
    // ALL triples; assert at least one triple has real 2D area.
    const pts = [...pos.values()];
    const area = (i: number, j: number, k: number) =>
      Math.abs(
        (pts[j]!.x - pts[i]!.x) * (pts[k]!.y - pts[i]!.y) -
          (pts[k]!.x - pts[i]!.x) * (pts[j]!.y - pts[i]!.y),
      );
    expect(area(0, 1, 2)).toBeGreaterThan(1);
  });

