    // sequence keeps f2 before f3 (faction ids sorted). Determinism: identical
    // inputs give identical output.
    const again = computeFocusPositions(
      [member("a", 0.9)],
      [member("x2", 0.1, "f2"), member("x1", 0.9, "f2"), member("y1", 0.5, "f3")],
    );
    expect(pos.get("x1")).toEqual(again.get("x1"));
    expect(pos.get("y1")).toEqual(again.get("y1"));
