import { afterEach, describe, expect, it } from "vitest";
import type { NodeSingular } from "cytoscape";
import {
  FOCUS_LABEL_COLOR_DARK,
  FOCUS_LABEL_COLOR_LIGHT,
  FOCUS_NODE_FALLBACK_COLOR,
  FOCUS_NODE_FALLBACK_RADIUS,
  focusStylesheet,
  labelColor,
  nodeColor,
  nodeDiameter,
  resolveFocusTheme,
} from "./focusStyle";

function fakeEle(data: Record<string, unknown>): NodeSingular {
  return { data: (k: string) => data[k] } as unknown as NodeSingular;
}

type SheetRule = { selector: string; style: Record<string, unknown> };

/** Find a rule by its exact selector string. */
function rule(sheet: ReturnType<typeof focusStylesheet>, selector: string): SheetRule | undefined {
  return sheet.find(
    (s): s is SheetRule => (s as { selector?: unknown }).selector === selector,
  );
}

/** Read the `color` off the `node` selector of a produced stylesheet. */
function nodeLabelColor(sheet: ReturnType<typeof focusStylesheet>): unknown {
  return rule(sheet, "node")?.style["color"];
}

describe("focusStyle mappers", () => {
  it("uses the node's own color and reach-derived diameter", () => {
    expect(nodeColor(fakeEle({ color: "#abcdef" }))).toBe("#abcdef");
    expect(nodeDiameter(fakeEle({ radius: 10 }))).toBe(20);
  });

  it("falls back for a node missing color or radius", () => {
    expect(nodeColor(fakeEle({}))).toBe(FOCUS_NODE_FALLBACK_COLOR);
    expect(nodeDiameter(fakeEle({}))).toBe(FOCUS_NODE_FALLBACK_RADIUS * 2);
  });

  it("returns a five-selector stylesheet (node, node[external], edge, edge mutual, edge external)", () => {
    expect(focusStylesheet()).toHaveLength(5);
  });
});

describe("focus edge arrows encode follow direction", () => {
  it("gives every edge a target arrowhead matching the line color", () => {
    const edge = rule(focusStylesheet("light"), "edge");
    expect(edge?.style["target-arrow-shape"]).toBe("triangle");
    expect(edge?.style["target-arrow-color"]).toBe(edge?.style["line-color"]);
  });

  it("adds a source arrowhead only for mutual (reciprocal) edges", () => {
    const sheet = focusStylesheet("light");
    expect(rule(sheet, "edge")?.style["source-arrow-shape"]).toBeUndefined();
    const mutual = rule(sheet, 'edge[direction = "mutual"]');
    expect(mutual?.style["source-arrow-shape"]).toBe("triangle");
    expect(mutual?.style["source-arrow-color"]).toBe(rule(sheet, "edge")?.style["line-color"]);
  });

  it("keeps cross-faction edges dashed but still arrowed", () => {
    const external = rule(focusStylesheet("light"), "edge[?external]");
    expect(external?.style["line-style"]).toBe("dashed");
    expect(external?.style["target-arrow-color"]).toBe(external?.style["line-color"]);
  });

  it("uses theme-aware edge + arrow colors legible on both grounds", () => {
    const light = rule(focusStylesheet("light"), "edge");
    const dark = rule(focusStylesheet("dark"), "edge");
    expect(light?.style["line-color"]).not.toBe(dark?.style["line-color"]);
    expect(light?.style["target-arrow-color"]).toBe(light?.style["line-color"]);
    expect(dark?.style["target-arrow-color"]).toBe(dark?.style["line-color"]);
  });
});

describe("focus label color is theme-aware", () => {
  it("resolves a dark ink label for light theme and a light label for dark theme", () => {
    expect(labelColor("light")).toBe(FOCUS_LABEL_COLOR_LIGHT);
    expect(labelColor("dark")).toBe(FOCUS_LABEL_COLOR_DARK);
    // Light label must be a dark ink (readable on the cream ground); dark
    // label must be near-white (readable on the dark ground).
    expect(FOCUS_LABEL_COLOR_LIGHT.toLowerCase()).toBe("#0f172a");
    expect(FOCUS_LABEL_COLOR_DARK).toBe("#E7EEF6");
  });

  it("stamps the theme's label color onto the node selector", () => {
    expect(nodeLabelColor(focusStylesheet("light"))).toBe(FOCUS_LABEL_COLOR_LIGHT);
    expect(nodeLabelColor(focusStylesheet("dark"))).toBe(FOCUS_LABEL_COLOR_DARK);
  });

  it("defaults to the readable (light) label when no theme is passed", () => {
    expect(nodeLabelColor(focusStylesheet())).toBe(FOCUS_LABEL_COLOR_LIGHT);
  });
});

describe("resolveFocusTheme", () => {
  afterEach(() => {
    delete document.documentElement.dataset["theme"];
    document.documentElement.classList.remove("dark");
  });

  it("honors an explicit data-theme attribute over the OS preference", () => {
    document.documentElement.dataset["theme"] = "dark";
    expect(resolveFocusTheme()).toBe("dark");
    document.documentElement.dataset["theme"] = "light";
    expect(resolveFocusTheme()).toBe("light");
  });

  it("treats a .dark class as dark when no data-theme is set", () => {
    document.documentElement.classList.add("dark");
    expect(resolveFocusTheme()).toBe("dark");
  });
});


