// design-ratchet-allow-file: canvas-render — focus-graph canvas colours, passed to a drawing API rather than rendered as
// classes. Same follow-up as GraphCanvas.
/**
 * focusStyle — the cytoscape stylesheet for the focus canvas, extracted as a
 * pure module. cytoscape resolves node size/color via mapper functions it calls
 * at render time against the <canvas> renderer, which jsdom can't run — keeping
 * the mappers here lets them be unit-tested directly instead of hiding
 * uncovered inside the component.
 */

import type cytoscape from "cytoscape";
import type { NodeSingular } from "cytoscape";
export const FOCUS_NODE_FALLBACK_COLOR = "#64748B";
export const FOCUS_NODE_FALLBACK_RADIUS = 8;

/**
 * Node label colors. cytoscape stylesheets are plain JS objects — they CANNOT
 * read CSS custom properties — so the label color has to be resolved explicitly
 * per theme. Light = the range `--cog-text-primary` ink (#0F172A), readable on
 * the cream focus ground; dark = near-white, readable on the dark ground. A
 * matching text-outline halo keeps the label legible even where it overlaps a
 * node fill.
 */
export const FOCUS_LABEL_COLOR_LIGHT = "#0F172A";
export const FOCUS_LABEL_COLOR_DARK = "#E7EEF6";

/** Outline halo behind the label — the focus ground color for each theme. */
const FOCUS_LABEL_OUTLINE_LIGHT = "#FAF9F6";
const FOCUS_LABEL_OUTLINE_DARK = "#0A0E14";

/**
 * Edge + arrowhead colors. Theme-aware like the labels so both the line and its
 * arrows stay legible on the cream (light) and near-black (dark) grounds; the
 * arrow color always tracks the line color. Cross-faction edges keep the blue
 * accent (legible on both grounds), arrows included.
 */
const FOCUS_EDGE_COLOR_LIGHT = "#475569";
const FOCUS_EDGE_COLOR_DARK = "#64748B";
const FOCUS_EDGE_EXTERNAL_COLOR = "#4C7EF3";

export type FocusTheme = "light" | "dark";

/**
 * resolveFocusTheme — the active visual theme for the focus canvas. Honors an
 * explicit `data-theme` on <html> (set by platform-chrome's ThemeProvider),
 * then a `.dark` class, and only then falls back to the OS preference. Mirrors
 * files-mfe's isDarkMode so the light theme is never broken for a dark-OS user.
 */
export function resolveFocusTheme(): FocusTheme {
  const theme = document.documentElement.dataset["theme"];
  if (theme === "dark") return "dark";
  if (theme === "light") return "light";
  if (document.documentElement.classList.contains("dark")) return "dark";
  return window.matchMedia?.("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

/** Node label color for a theme — dark ink on light, near-white on dark. */
export function labelColor(theme: FocusTheme): string {
  return theme === "dark" ? FOCUS_LABEL_COLOR_DARK : FOCUS_LABEL_COLOR_LIGHT;
}

/** Node fill = its faction color, or a neutral fallback. */
export function nodeColor(ele: NodeSingular): string {
  return (ele.data("color") as string) ?? FOCUS_NODE_FALLBACK_COLOR;
}

/** Node diameter = reach radius × 2, falling back to a small default. */
export function nodeDiameter(ele: NodeSingular): number {
  return ((ele.data("radius") as number) || FOCUS_NODE_FALLBACK_RADIUS) * 2;
}

export function focusStylesheet(theme: FocusTheme = "light"): cytoscape.StylesheetJson {
  const isDark = theme === "dark";
  const edgeColor = isDark ? FOCUS_EDGE_COLOR_DARK : FOCUS_EDGE_COLOR_LIGHT;
  return [
    {
      selector: "node",
      style: {
        "background-color": nodeColor,
        width: nodeDiameter,
        height: nodeDiameter,
        label: "data(label)",
        color: labelColor(theme),
        "text-outline-color": isDark ? FOCUS_LABEL_OUTLINE_DARK : FOCUS_LABEL_OUTLINE_LIGHT,
        "text-outline-width": 2,
        "font-size": "10px",
        "text-valign": "bottom",
        "text-margin-y": 4,
        "border-width": 2,
        "border-color": "#0A0E14",
      },
    },
    {
      selector: "node[?external]",
      style: { "border-color": "#9DAABB", "border-style": "dashed" },
    },
    {
      selector: "edge",
      style: {
        width: 1.3,
        "line-color": edgeColor,
        "line-opacity": 0.6,
        "curve-style": "bezier",
        "target-arrow-shape": "triangle",
        "target-arrow-color": edgeColor,
        "arrow-scale": 0.8,
