  it("falls back to a neutral color when members omit color and radius", () => {
    const els: CyElement[] = [
      { data: { id: "a" } },
      { data: { id: "b" } },
      edge("a", "b"),
    ];
    const layout = layoutThumbnail(els, 100);
    expect(layout.nodes.every((n) => n.color === "#888")).toBe(true);
